import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Hearth OS · 可观测性与首次引导设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-可观测性与首次引导设计说明.md","filePath":"architecture/Hearth-可观测性与首次引导设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-可观测性与首次引导设计说明.md"};function h(s,t,c,l,n,i){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="hearth-os-·-可观测性与首次引导设计说明" tabindex="-1">Hearth OS · 可观测性与首次引导设计说明 <a class="header-anchor" href="#hearth-os-·-可观测性与首次引导设计说明" aria-label="Permalink to &quot;Hearth OS · 可观测性与首次引导设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下健康、诊断、引导相关文件，以及维护服务的对外快照与前端对应消费点），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>加密、备份与恢复、多设备同步、维护清理与数据生命周期</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td><strong>完全不重复</strong>，只在末尾列端点用途</td></tr><tr><td>各后台周期任务的间隔对比</td><td><a href="./定时任务设计说明.html">定时任务设计说明</a></td><td>不重复</td></tr><tr><td>前端整体状态管理与事件桥</td><td><a href="./Hearth-前端架构设计说明.html">Hearth-前端架构设计说明</a></td><td>只讲这几个页面的轮询与下载动作</td></tr></tbody></table><p>本文只讲：<strong>系统怎么告诉外界「现在好不好」、能导出什么、以及第一次打开时怎么判断要不要引导</strong>。这一层非常薄，本文如实按代码规模说明，不做补全式推测。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>这是三个无状态的只读聚合服务（健康、诊断、引导，合计约三百行）：把存储与运行时状态拼成快照供界面轮询与下载，几乎不含业务决策。真正的运维能力（备份、同步、维护）都在别处，本文不碰。</p><hr><h2 id="_1-先定性-四个容易误解的地方" tabindex="-1">1. 先定性：四个容易误解的地方 <a class="header-anchor" href="#_1-先定性-四个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：四个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为「降级」会综合判断执行器、调度器、停止开关</td><td>只有三条规则能触发降级；执行器不可用、调度器停止、停止开关开启都<strong>只上报不降级</strong></td></tr><tr><td>以为降级会返回非 200</td><td>健康接口始终返回 200，状态只体现在响应体里</td></tr><tr><td>以为诊断导出做了字段级脱敏</td><td>它主要是「不导出任何明细，只给计数与类型名」；唯一的显式脱敏是维护错误里的本地路径替换</td></tr><tr><td>以为引导检查项都是门槛</td><td>只有「聊天模型是否已配置」决定要不要引导，其余三项纯展示</td></tr></tbody></table><hr><h2 id="_2-健康快照-都看什么" tabindex="-1">2. 健康快照：都看什么 <a class="header-anchor" href="#_2-健康快照-都看什么" aria-label="Permalink to &quot;2. 健康快照：都看什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>内容</th></tr></thead><tbody><tr><td>总体</td><td>状态（正常 / 降级）、应用名、当前时间、启动时间、运行时长、schema 版本、实例编号</td></tr><tr><td>进程</td><td>常驻内存、堆已用、堆总量</td></tr><tr><td>磁盘</td><td>可用空间、数据库文件大小、预写日志大小（读取失败按 0 处理）</td></tr><tr><td>任务</td><td>总数，以及排队、运行中、可继续、等待审批四项分状态计数</td></tr><tr><td>维护</td><td>最近一次运行时间与状态、最近错误</td></tr><tr><td>调度与安全</td><td>调度器是否启用且在运行、全局停止开关是否拉下</td></tr><tr><td>执行器</td><td>Codex 是否可跑、供应商与模型、鉴权来源、问题清单；Hermes 健康</td></tr><tr><td>问题列表</td><td>触发降级的具体原因</td></tr></tbody></table><p><strong>触发降级只有三条</strong>：schema 版本与代码期望值不一致、最近一次维护失败、可用磁盘低于 256 MB。问题列表非空即为降级，否则正常。</p><p>健康接口在快照之上还会额外叠加两块<strong>前端专用</strong>字段：聊天模型是否已配置及其视图、以及 Codex 的配置路径、主目录、基础地址、线协议、密钥变量名与「密钥是否存在」。所以直接拿共享契约里的健康快照类型去解析这个接口，会漏掉这些字段。</p><p>前端每 20 秒轮询一次，按状态显示「正常 / 需要关注」，展示运行时长、内存、可用磁盘、数据库与日志大小、五项任务计数、调度器状态、停止开关、schema 版本与实例编号前 8 位、Codex 状态或问题清单，并逐条渲染告警。</p><hr><h2 id="_3-诊断导出-聚合而非明细" tabindex="-1">3. 诊断导出：聚合而非明细 <a class="header-anchor" href="#_3-诊断导出-聚合而非明细" aria-label="Permalink to &quot;3. 诊断导出：聚合而非明细&quot;">​</a></h2><p>导出是一份带格式标记与版本号的 JSON，包含四块：</p><ol><li><strong>健康快照</strong>（上一节全部内容）；</li><li><strong>最近 10 次维护记录</strong>；</li><li><strong>运行时环境</strong>：Node 版本、平台、架构、进程号；</li><li><strong>规模统计</strong>：七张表的行数（事件、任务、运行、审批、产物、记忆、方法候选），以及按类型分组、取前 30 名的事件类型计数。</li></ol><p>另有三个检查标记：前端编译产物是否存在、是否仅本机可访问、备份是否强制加密。<strong>后两个是硬编码为真，不是实时检测结果</strong>，这一点读代码时尤其容易高估。</p><p>响应头设为不缓存、JSON 类型、并带日期命名的附件下载名；界面上就是一个「下载脱敏诊断」链接。所谓脱敏，实际靠的是「只给行数、类型名、数值，不给任何任务/记忆/事件正文」这一设计，加上维护错误里把本地盘符路径替换成占位符并截断到 500 字符。</p><hr><h2 id="_4-首次引导-一个门槛-三个展示项" tabindex="-1">4. 首次引导：一个门槛，三个展示项 <a class="header-anchor" href="#_4-首次引导-一个门槛-三个展示项" aria-label="Permalink to &quot;4. 首次引导：一个门槛，三个展示项&quot;">​</a></h2><p>引导状态只有两种值：已完成、已跳过，附带完成时间；读取时会严格校验，格式不对就当作「从未引导过」。</p><p><strong>是否需要引导的唯一判据</strong>：从未完成或跳过引导，<strong>且</strong>聊天模型还没配置。其它三项检查（可用执行器列表、记忆自动捕获开关、主动式是否启用）只用于向导页展示，不参与门禁。这三个判定都是装配时以惰性闭包注入的，可用执行器取自执行器清单里健康探测为可跑的那些。</p><p>由此产生一个后果：一旦用户完成或跳过了引导，即使后来把模型配置删掉，也不会再弹出引导。</p><p>前端门禁只在首页路径生效：若接口返回需要引导，就重定向到欢迎页；该查询的缓存有效期是 10 秒。向导页用主动式检查项初始化偏好（未引导过时默认开启）。</p><hr><h2 id="_5-其余运维端点-仅列用途-不展开实现" tabindex="-1">5. 其余运维端点（仅列用途，不展开实现） <a class="header-anchor" href="#_5-其余运维端点-仅列用途-不展开实现" aria-label="Permalink to &quot;5. 其余运维端点（仅列用途，不展开实现）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>端点用途</th></tr></thead><tbody><tr><td>维护</td><td>查看最近运行与策略、手动触发一次运行</td></tr><tr><td>备份</td><td>列表、创建、下载、按编号恢复、整体恢复；另有一个固定返回「必须加密备份」错误的守门端点，用来禁止明文备份</td></tr><tr><td>同步</td><td>查看状态、新增/拉取/轮换/吊销对端、解决冲突、以及唯一允许非本机入站的事件导出端点</td></tr></tbody></table><p>这些端点的实现分别见<a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a>（备份、同步、维护算法）与<a href="./Hearth-服务组装与API接入设计说明.html">Hearth-服务组装与API接入设计说明</a>（入站白名单例外）。它们默认都受仅本机访问的安全钩子约束。</p><hr><h2 id="_6-只读代码才会发现的事实" tabindex="-1">6. 只读代码才会发现的事实 <a class="header-anchor" href="#_6-只读代码才会发现的事实" aria-label="Permalink to &quot;6. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>降级只有三条规则，且健康接口永远返回 200。</li><li>健康接口返回的字段比共享契约里的健康快照更多，多出来的是前端专用字段。</li><li>诊断导出的两个安全标记是常量真值，不是运行时校验。</li><li>引导只看模型配置；一旦完成或跳过就永久不再触发。</li><li>这三个服务都是无状态只读聚合，源码规模很小；本模块没有其它散落的运维或引导机制。</li></ol><hr><h2 id="_7-与其它模块的分界" tabindex="-1">7. 与其它模块的分界 <a class="header-anchor" href="#_7-与其它模块的分界" aria-label="Permalink to &quot;7. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>存储层的计数与元数据、schema 版本常量、执行器健康探测、装配时注入的调度器状态与四个引导判定</td></tr><tr><td>输出</td><td>健康快照、诊断导出文件、引导状态与检查项、若干运维端点</td></tr><tr><td>不讲</td><td>备份/同步/维护的算法（存储）、周期任务间隔（定时任务）、安全钩子（服务组装）、前端整体架构（前端）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>健康快照与三条降级规则</td><td><code>apps/server/src/health.ts</code></td></tr><tr><td>诊断导出结构</td><td><code>apps/server/src/diagnostics.ts</code></td></tr><tr><td>引导状态与门禁判定</td><td><code>apps/server/src/onboarding.ts</code></td></tr><tr><td>维护快照与错误脱敏</td><td><code>apps/server/src/maintenance.ts</code></td></tr><tr><td>备份、同步、维护的实现（本文不展开）</td><td><code>apps/server/src/backups.ts</code>、<code>sync.ts</code>、<code>maintenance.ts</code></td></tr><tr><td>端点装配与前端专用字段</td><td><code>apps/server/src/app.ts</code></td></tr><tr><td>契约类型</td><td><code>packages/core/src/types.ts</code></td></tr><tr><td>前端消费</td><td><code>apps/web/src/lib/api.ts</code>、<code>lib/types.ts</code>、<code>pages/OperationsPage.tsx</code>、<code>pages/OnboardingPage.tsx</code>、<code>App.tsx</code></td></tr></tbody></table>',42)])])}const _=d(o,[["render",h]]);export{b as __pageData,_ as default};
